using System;
using System.Drawing;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace OpenAntiLag {
 public sealed class SetupWizard:Form {
  readonly PlayerContext context;readonly Label title=PlayerUi.Text("Добро пожаловать",22,true),description=PlayerUi.Text("",11,false,Theme.Muted);readonly ComboBox games=PlayerUi.Choice(),profiles=PlayerUi.Choice("Стандартный","Соревновательный","Пользовательский");readonly CheckBox automatic=new CheckBox {Text="Разрешаю автоматическое применение этого профиля при запуске игры",AutoSize=true};readonly Button next=PlayerUi.Button("Продолжить",null,true),skip=PlayerUi.Button("Пропустить"),scan=PlayerUi.Button("Найти игры");readonly TableLayoutPanel body=new TableLayoutPanel {Dock=DockStyle.Top,ColumnCount=1,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,Padding=new Padding(24)};int step;
  public SetupWizard(PlayerContext context){this.context=context;Text="Настройка Open AntiLag";BackColor=Theme.Background;ForeColor=Theme.Text;Font=new Font("Segoe UI",10);AutoScroll=true;ClientSize=new Size(620,520);MinimumSize=new Size(550,480);StartPosition=FormStartPosition.CenterParent;Icon=WindowTheme.AppIcon();Shown+=delegate{var area=Screen.FromControl(this).WorkingArea;MinimumSize=new Size(Math.Min(MinimumSize.Width,area.Width-24),Math.Min(MinimumSize.Height,area.Height-24));Size=new Size(Math.Min(Width,area.Width-24),Math.Min(Height,area.Height-24));};Resize+=delegate{var max=new Size(Math.Max(140,ClientSize.Width-70),0);title.MaximumSize=max;description.MaximumSize=max;};body.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));foreach(Control control in new Control[]{title,description,scan,games,profiles,automatic,next,skip}){body.Controls.Add(control);body.RowStyles.Add(new RowStyle(SizeType.AutoSize));control.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right;}Controls.Add(body);scan.Click+=async delegate{scan.Enabled=false;try{await context.Scan();FillGames();}catch(Exception error){description.Text=error.Message;}finally{scan.Enabled=true;}};next.Click+=delegate{try{if(step==0){if(games.SelectedItem is InstalledGame)context.Select((InstalledGame)games.SelectedItem);profiles.SelectedIndex=(int)context.Profile;step=1;}else if(step==1){context.SetProfile((PlayerProfile)profiles.SelectedIndex);step=2;}else{if(automatic.Checked){if(!PlayerUi.Confirm(this,"Автоматическое применение",OptimizationOrchestrator.Summary(OptimizationOrchestrator.Options(context.Profile),new string[0])+"\n\nРазрешить автоматическое применение и последующий откат для выбранной игры?",context.Preview))return;context.SetAutomatic(true);}else if(context.Selected!=null&&context.Selected.Automatic)context.SetAutomatic(false);context.Preferences.SetupComplete=true;context.Save();DialogResult=DialogResult.OK;Close();return;}Render();}catch(Exception error){description.Text=error.Message;}};skip.Click+=delegate{context.Preferences.SetupComplete=true;context.Save();Close();};FillGames();Render();}
  void FillGames(){games.Items.Clear();foreach(var game in context.Preferences.Games)games.Items.Add(game);games.DisplayMember="Name";if(context.Selected!=null)games.SelectedItem=context.Selected;else if(games.Items.Count>0)games.SelectedIndex=0;}
  void Render(){title.Text=(step+1)+" / 3  ·  "+(step==0?"Найдём ваши игры":step==1?"Выберите профиль":"Всё под вашим контролем");scan.Visible=games.Visible=step==0;profiles.Visible=step==1;automatic.Visible=step==2;next.Text=step==2?"Завершить настройку":"Продолжить";description.MaximumSize=new Size(Math.Max(100,body.Width-60),0);description.Text=step==0?"OpenAntiLag читает локальные Steam-библиотеки. Игру также можно добавить вручную после мастера. Интернет не нужен.":step==1?"Стандартный: игровой режим Windows. Соревновательный: дополнительно отключает запись Xbox. Пользовательский: ваши настройки с отдельным просмотром. Прирост FPS не гарантируется.":"Доступен профиль Windows с обратимыми изменениями. Видеокарта и дополнительные модули проверяются отдельно. Автоматически не применяются настройки с UAC, ограничения интернета, DNS или шейдеры.\n\n"+context.Optimizer.Status.Message;automatic.Enabled=context.Selected!=null&&context.Selected.CanWatch&&context.Profile!=PlayerProfile.Custom&&!context.LibraryReadOnly;if(!automatic.Enabled)automatic.Checked=false;}
 }
 public sealed class PlayerWorkspace:UserControl {
  public readonly PlayerContext Context;public readonly NavigationController Navigation=new NavigationController();readonly ExpertHost expert;readonly System.Windows.Forms.Timer timer=new System.Windows.Forms.Timer {Interval=3000};bool started;
  public PlayerWorkspace(PlayerContext context,TabControl tools,Func<ProfileOptions> custom,Func<string[]> machine){Context=context;Dock=DockStyle.Fill;Name="playerWorkspace";Controls.Add(Navigation);expert=new ExpertHost(tools,()=>Navigation.ShowPage(Navigation.Current??"Settings"));Action<string> navigate=key=>Navigation.ShowPage(key);Navigation.Register("Home","Главная",new DashboardPage(context,navigate,custom,machine));Navigation.Register("Games","Мои игры",new GamesPage(context));Navigation.Register("Optimization","Оптимизация",new OptimizationPage(context,ShowExpert,navigate));Navigation.Register("Results","Результаты",new ResultsPage(context,ShowExpert));Navigation.Register("Settings","Настройки",new SettingsPage(context,ShowExpert,navigate,ShowWizard));Navigation.Register("Recovery","Восстановление",new RecoveryPage(context));var internet=new InternetPage(context,ShowExpert);Navigation.RegisterDetail("Internet",internet);Navigation.AddVersion();timer.Tick+=async delegate{await context.Tick();};Navigation.ShowPage("Home");}
  public async Task Start(){if(started)return;started=true;await Context.Initialize();if(!Context.Preview){timer.Start();if(!Context.Preferences.SetupComplete&&!Context.Optimizer.Status.HasProfile)ShowWizard();}}
  public void ShowWizard(){using(var wizard=new SetupWizard(Context))wizard.ShowDialog(FindForm());Navigation.ShowPage("Home");Context.Emit();}
  public void ShowExpert(int index,string title){if(Context.Session.Faceit&&(index==0||index==1||index==2||index==3||index==5)&&!PlayerUi.Confirm(this,"Дополнительные действия и FACEIT","Обнаружен FACEIT. Официальная совместимость не подтверждена. Этот раздел содержит глобальные или экспериментальные настройки, выключенные по умолчанию. Открыть его для ручной настройки?",Context.Preview))return;Navigation.ShowDetail(expert);expert.Select(index,title);}
  public async Task PrepareExit(){await Context.Session.RestoreOwned();}
  protected override void Dispose(bool disposing){if(disposing){timer.Stop();timer.Dispose();Context.Dispose();expert.Dispose();}base.Dispose(disposing);}
 }
}
